 private static void need(boolean value,String label){if(!value)throw new AssertionError("Large Door render: "+label);}
 private static int choice(java.util.function.Predicate<ModernFinishCatalog.Entry> predicate){for(int i=0;i<ModernFinishCatalog.ENTRIES.size();i++)if(predicate.test(ModernFinishCatalog.ENTRIES.get(i)))return i;throw new AssertionError("Missing required native catalog sample");}
 private static void prepare(){var mc=Minecraft.getInstance();var wall=NativePanelPlaybackRenderer.currentBake();need(wall!=null,"coherent material bake");bake=new NativeDoorRenderer.Bake(id->{var model=mc.getModelManager().getModel(ModelResourceLocation.standalone(ResourceLocation.parse(id)));return id.endsWith("space_standard_rotating_door_framed_left_leaf")?new net.neoforged.neoforge.client.model.BakedModelWrapper<BakedModel>(model){}:model;},material->mc.getTextureAtlas(material.atlasLocation()).apply(material.texture()),wall);scenes=new NativeProgrammableDoorEntity.Visual[12];
  int authored=choice(e->e.visible()&&e.frame()!=null&&e.frame().border()),surface=choice(e->e.visible()&&e.general()&&e.id().contains("dark")),company=choice(e->e.id().equals("company_door_pinnacle_light"));
  for(int i=0;i<scenes.length;i++){boolean sliding=i==2||i==3||i==8||i==7;int design=i==1||i==6||i==7?0:i==2?7:2,depth=i==8?0:1,direction=i==3?1:i==7?3:0;var base=NativeDoorSettings.fresh(false,sliding);int face=i==5?company:-1,security=i==9||i==10?1:0;var frame=i==4?new FrameSettings(authored,surface,-2,0,-1,-1,false,false,false,false):base.frames();var glass=i==6?new NativeDoorGlass(-1,14,2,0):i==7?new NativeDoorGlass(surface,0,0,0):NativeDoorGlass.DEFAULT;var settings=new NativeDoorSettings(new SpaceDoorData(design,1,i!=11,direction,depth==0,sliding,i!=4&&i!=11,0,true),face,0,false,depth,i==8?2:1,security,127,frame,glass);var state=fixture.defaultBlockState().setValue(NativeProgrammableDoorBlock.FACING,Direction.SOUTH).setValue(NativeProgrammableDoorBlock.HINGE,DoorHingeSide.RIGHT);var side=sliding?SpaceDoorControlPanel.Side.RIGHT:SpaceDoorControlPanel.Side.LEFT;var readers=NativeDoorCredentialService.EMPTY;if(i==10){var projection=new NativeDoorCredentialService.Side(new NativeTokenReader.Visual(false,1,1,false,0,false),new NativeTokenReader.Motion(0,20,false,12,201));readers=new NativeDoorCredentialService.Projection(projection,projection);}scenes[i]=new NativeProgrammableDoorEntity.Visual(settings,state,side,true,i==11,readers);}
 }
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(!"true".equals(System.getenv("VANDOR_LARGE_DOOR_RENDER_CHECK"))||done||!(event.getScreen() instanceof net.minecraft.client.gui.screens.TitleScreen))return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(bake==null)prepare();var graphics=event.getGuiGraphics();graphics.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);graphics.flush();var buffers=mc.renderBuffers().bufferSource();for(int i=0;i<scenes.length;i++){int x=10+(i%6)*105,y=15+(i/6)*175;graphics.enableScissor(x,y,x+100,y+165);var poses=graphics.pose();poses.pushPose();try{poses.translate(x+3,y+150,300);poses.scale(30,-30,30);poses.translate(1.5,1.5,.5);poses.mulPose(com.mojang.math.Axis.YP.rotationDegrees(i==8?110:i==9||i==10?-110:scenes[i].settings().door().sliding?20:-20));poses.translate(-1.5,-1.5,-.5);float progress=i==0?.35F:i==2?.2F+.05F*frames:i==3?1:i==7?.55F:0;var scene=scenes[i];if(i==8&&frames<5)scene=new NativeProgrammableDoorEntity.Visual(scene.settings(),scene.state(),SpaceDoorControlPanel.Side.NONE,true,false,scene.readers());if(i==10&&frames<5){var reader=new NativeDoorCredentialService.Side(scene.readers().front().visual(),new NativeTokenReader.Motion(0,20,false,0,200));scene=new NativeProgrammableDoorEntity.Visual(scene.settings(),scene.state(),scene.side(),true,false,new NativeDoorCredentialService.Projection(reader,reader));}NativeDoorRenderer.renderLargeAt(bake,scene,mc,new BlockPos(i,0,0),progress,frames*.01,poses,buffers,0xf000f0,OverlayTexture.NO_OVERLAY);}finally{poses.popPose();}buffers.endBatch();graphics.flush();graphics.disableScissor();}if(frames==0)warmedBuilds=bake.meshBuilds();else need(bake.meshBuilds()==warmedBuilds,"motion reused prepared meshes");capture=++frames>=10;}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event)throws Exception{if(done||(!capture&&frames!=5))return;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){double pixelscale=mc.getWindow().getGuiScale();int nw=(int)(100*pixelscale),nh=(int)(150*pixelscale),nx=(int)(220*pixelscale),ny=(int)(190*pixelscale);if(frames==5){numericBaseline=new int[nw*nh];securityBaseline=new int[nw*nh];for(int y=0;y<nh;y++)for(int x=0;x<nw;x++){numericBaseline[y*nw+x]=image.getPixelRGBA(nx+x,ny+y);securityBaseline[y*nw+x]=image.getPixelRGBA((int)(430*pixelscale)+x,ny+y);}return;}int numericChanges=0,securityChanges=0;for(int y=0;y<nh;y++)for(int x=0;x<nw;x++)if(x>=20*pixelscale&&x<38*pixelscale&&y>=105*pixelscale&&y<125*pixelscale&&numericBaseline[y*nw+x]!=image.getPixelRGBA(nx+x,ny+y))numericChanges++;for(int y=0;y<nh;y++)for(int x=0;x<nw;x++){int current=image.getPixelRGBA((int)(430*pixelscale)+x,ny+y);if((current&0xffffff)==0x40b3ff&&current!=securityBaseline[y*nw+x])securityChanges++;}done=true;need(securityChanges>5,"new security rejection glyph vs nonrejected reader "+securityChanges);System.out.println("[vandorlabs][large-door-render] controls numericPixelChanges="+numericChanges+" newRejectionPixels="+securityChanges+" meshBuilds="+bake.meshBuilds()+" snapshotBytes="+bake.snapshotBytes());need(numericChanges>10,"actual numeric/rear-pad pixels vs absent-pad control "+numericChanges);var path=mc.gameDirectory.toPath().resolve("screenshots/large-door-native.png");java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);double scale=mc.getWindow().getGuiScale();for(int i=0;i<scenes.length;i++){int changed=0,x0=10+(i%6)*105,y0=15+(i/6)*175;for(int y=(int)(y0*scale);y<(int)((y0+150)*scale);y++)for(int x=(int)(x0*scale);x<(int)((x0+100)*scale);x++)if((image.getPixelRGBA(x,y)&0xffffff)!=0x302820)changed++;if(i==10){int amber=0;for(int y=(int)(y0*scale);y<(int)((y0+150)*scale);y++)for(int x=(int)(x0*scale);x<(int)((x0+100)*scale);x++)if((image.getPixelRGBA(x,y)&0xffffff)==0x40b3ff)amber++;need(amber>5,"actual security-reader amber glyph "+amber);}need(changed>200,"visible authored scene="+i+" pixels="+changed);}need(bake.snapshotBytes()<=16*1024*1024,"retained snapshot byte budget");}done=true;System.out.println("[vandorlabs][large-door-render] title PASS scenes=12 paired1.5/Xclipping authoredbody/panes, sideways/vertical motion, frame/interior/face/glass/company overrides, numeric/rear/security pads and visible recovery owner; no world/server or placed-door claim");mc.stop();}
